// Advanced Lead Scoring Algorithm for Insurance
// Scores leads 0-100 based on multiple factors

const lead = $input.first().json;

let score = 0;
const scoreReasons = [];
const warnings = [];

// === INCOME SCORING (30 points max) ===
const income = parseInt(lead.annualIncome) || 0;
if (income >= 75000) {
  score += 30;
  scoreReasons.push('High income bracket (+30)');
} else if (income >= 50000) {
  score += 20;
  scoreReasons.push('Mid-high income (+20)');
} else if (income >= 35000) {
  score += 10;
  scoreReasons.push('Mid income (+10)');
} else if (income > 0) {
  score += 5;
  scoreReasons.push('Low income (+5)');
  warnings.push('Income below ideal threshold');
} else {
  warnings.push('Income not provided');
}

// === TIMELINE/URGENCY SCORING (25 points max) ===
const timeline = (lead.timeline || '').toLowerCase();
if (timeline.includes('immediate') || timeline.includes('asap') || timeline === 'now') {
  score += 25;
  scoreReasons.push('Immediate need (+25)');
} else if (timeline.includes('week') || timeline.includes('30') || timeline === 'this_month') {
  score += 20;
  scoreReasons.push('Short-term need (+20)');
} else if (timeline.includes('month') || timeline.includes('90')) {
  score += 10;
  scoreReasons.push('Medium-term timeline (+10)');
} else {
  score += 5;
  warnings.push('No urgency indicated');
}

// === AGE SCORING (15 points max) ===
const age = parseInt(lead.age) || 0;
if (age >= 25 && age <= 65) {
  score += 15;
  scoreReasons.push('Ideal age range (+15)');
} else if (age >= 18 && age <= 75) {
  score += 10;
  scoreReasons.push('Acceptable age range (+10)');
} else if (age > 0) {
  score += 3;
  warnings.push('Age outside prime range');
}

// === INSURANCE TYPE SCORING (15 points max) ===
const insuranceType = (lead.insuranceType || '').toLowerCase();
const highValueTypes = ['life', 'whole life', 'universal', 'term life'];
const mediumValueTypes = ['health', 'medicare', 'aca', 'supplemental'];

if (highValueTypes.some(type => insuranceType.includes(type))) {
  score += 15;
  scoreReasons.push('High-value insurance type (+15)');
} else if (mediumValueTypes.some(type => insuranceType.includes(type))) {
  score += 10;
  scoreReasons.push('Medium-value insurance type (+10)');
} else if (insuranceType) {
  score += 5;
  scoreReasons.push('Insurance type specified (+5)');
} else {
  warnings.push('Insurance type not specified');
}

// === EMPLOYMENT STATUS (10 points max) ===
const employment = (lead.employmentStatus || '').toLowerCase();
if (employment.includes('full') || employment.includes('self-employed')) {
  score += 10;
  scoreReasons.push('Stable employment (+10)');
} else if (employment.includes('part')) {
  score += 5;
  scoreReasons.push('Part-time employment (+5)');
} else if (employment.includes('retired')) {
  score += 8;
  scoreReasons.push('Retired status (+8)');
}

// === CURRENT COVERAGE BONUS (5 points) ===
const currentCoverage = (lead.currentCoverage || '').toLowerCase();
if (currentCoverage === 'yes' || currentCoverage.includes('has')) {
  score += 5;
  scoreReasons.push('Has existing coverage - upsell opportunity (+5)');
}

// === LEAD SOURCE QUALITY ADJUSTMENT ===
const leadSource = (lead.leadSource || '').toLowerCase();
const premiumSources = ['referral', 'organic', 'direct'];
const goodSources = ['google', 'facebook', 'linkedin'];
const lowQualitySources = ['aged', 'bulk', 'shared'];

if (premiumSources.some(src => leadSource.includes(src))) {
  score += 5;
  scoreReasons.push('Premium lead source (+5)');
} else if (lowQualitySources.some(src => leadSource.includes(src))) {
  score -= 10;
  scoreReasons.push('Low-quality source (-10)');
  warnings.push('Lead from low-quality source');
}

// === GEOGRAPHIC SCORING ===
const state = (lead.state || '').toUpperCase();
const highValueStates = ['CA', 'NY', 'TX', 'FL', 'IL'];
if (highValueStates.includes(state)) {
  score += 5;
  scoreReasons.push('High-value state (+5)');
}

// === DETERMINE QUALIFICATION STATUS ===
let status = 'DISQUALIFIED';
let priority = 'LOW';
let assignmentRule = 'do_not_assign';

if (score >= 75) {
  status = 'HOT_LEAD';
  priority = 'URGENT';
  assignmentRule = 'top_performer';
} else if (score >= 60) {
  status = 'QUALIFIED';
  priority = 'HIGH';
  assignmentRule = 'round_robin';
} else if (score >= 40) {
  status = 'POTENTIAL';
  priority = 'MEDIUM';
  assignmentRule = 'nurture_sequence';
} else if (score >= 25) {
  status = 'LOW_PRIORITY';
  priority = 'LOW';
  assignmentRule = 'long_term_nurture';
}

// === CALCULATE ROI ESTIMATE ===
let estimatedValue = 0;
if (insuranceType.includes('life') || insuranceType.includes('whole')) {
  estimatedValue = income * 0.15; // 15% of annual income typical commission
} else if (insuranceType.includes('health') || insuranceType.includes('medicare')) {
  estimatedValue = 500; // Average health insurance commission
}

// === RETURN ENRICHED LEAD DATA ===
return {
  json: {
    ...lead,
    qualificationScore: score,
    status: status,
    priority: priority,
    assignmentRule: assignmentRule,
    scoreReasons: scoreReasons,
    warnings: warnings,
    estimatedValue: estimatedValue,
    processedAt: new Date().toISOString(),
    shouldContact: score >= 40,
    recommendedAction: score >= 75 ? 'Call within 5 minutes' : 
                       score >= 60 ? 'Call within 1 hour' :
                       score >= 40 ? 'Add to follow-up sequence' :
                       'Add to long-term nurture'
  }
};

