=<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; text-align: center; border-radius: 10px 10px 0 0; }
    .score-badge { background: #fff; color: #667eea; padding: 10px 20px; border-radius: 20px; font-size: 24px; font-weight: bold; display: inline-block; margin-top: 10px; }
    .content { background: #f9f9f9; padding: 30px; border-radius: 0 0 10px 10px; }
    .info-row { margin: 15px 0; padding: 10px; background: white; border-left: 4px solid #667eea; }
    .label { font-weight: bold; color: #667eea; }
    .urgent { background: #ff4444; color: white; padding: 15px; border-radius: 5px; margin: 20px 0; text-align: center; font-weight: bold; }
    .action-btn { background: #28a745; color: white; padding: 15px 30px; text-decoration: none; border-radius: 5px; display: inline-block; margin: 20px 0; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🔥 HOT LEAD ALERT!</h1>
      <div class="score-badge">Score: {{ $json.qualificationScore }}/100</div>
    </div>
    <div class="content">
      <div class="urgent">
        ⚡ ACTION REQUIRED: {{ $json.recommendedAction }}
      </div>

      <h2>Lead Information</h2>
      <div class="info-row">
        <span class="label">Name:</span> {{ $json.firstName }} {{ $json.lastName }}
      </div>
      <div class="info-row">
        <span class="label">Email:</span> {{ $json.email }}
      </div>
      <div class="info-row">
        <span class="label">Phone:</span> {{ $json.phone }}
      </div>
      <div class="info-row">
        <span class="label">Location:</span> {{ $json.state }} - {{ $json.zipCode }}
      </div>
      <div class="info-row">
        <span class="label">Insurance Type:</span> {{ $json.insuranceType }}
      </div>
      <div class="info-row">
        <span class="label">Annual Income:</span> ${{ $json.annualIncome }}
      </div>
      <div class="info-row">
        <span class="label">Timeline:</span> {{ $json.timeline }}
      </div>
      <div class="info-row">
        <span class="label">Estimated Value:</span> ${{ $json.estimatedValue }}
      </div>

      <h3>Why This Lead Scored High:</h3>
      <ul>
        {{#each $json.scoreReasons}}
        <li>{{ this }}</li>
        {{/each}}
      </ul>

      <a href="https://airtable.com/{{ $json.leadId }}" class="action-btn">View in CRM →</a>
    </div>
  </div>
</body>
</html>
